function validarCorreo(t){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(t)}function soloLetras(t){return/^[A-Za-zÁÉÍÓÚáéíóúÑñ\s]+$/.test(t)}function validarLongitud(t,e){return Math.abs(t).toString().length<=e}function calcularEdad(t){const e=new Date(t),a=new Date;let n=a.getFullYear()-e.getFullYear();const r=a.getMonth(),o=e.getMonth();return(r<o||r===o&&a.getDate()<e.getDate())&&n--,n}function esMayorDeEdad(t){return calcularEdad(t)>=18}function validarPassword(t){return/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).{8,}$/.test(t)}function capitalizarTexto(t){return t.toLowerCase().split(" ").filter(t=>t.length>0).map(t=>t.charAt(0).toUpperCase()+t.slice(1)).join(" ")}function calcularDiasRestantes(t){const e=new Date;e.setHours(0,0,0,0);const a=new Date(t);a.setHours(0,0,0,0);const n=a-e,r=Math.ceil(n/864e5);return r>0?r:0}